function iconGraphic(id){
 const svg=document.createElementNS("http://www.w3.org/2000/svg","svg");
 svg.setAttribute("viewBox","0 0 24 24");svg.setAttribute("fill","none");svg.setAttribute("stroke","currentColor");
 svg.setAttribute("stroke-width","1.8");svg.setAttribute("stroke-linecap","round");svg.setAttribute("stroke-linejoin","round");
 svg.classList.add("card-symbol-icon");
 if(EXTENDED_ICON_DATA[id]){
   svg.setAttribute("viewBox",EXTENDED_ICON_DATA[id][0]);
   svg.setAttribute("fill","currentColor");
   svg.setAttribute("stroke","none");
   svg.innerHTML=EXTENDED_ICON_DATA[id][1];
 } else {
   svg.innerHTML=BUILTIN_ICON_PATHS[id]||BUILTIN_ICON_PATHS.star;
 }
 return svg;
}
function cardVisual(c, cls="answer-card__emoji"){
 if(c.visualType==="icon" && (BUILTIN_ICON_PATHS[c.iconId]||EXTENDED_ICON_DATA[c.iconId]))return iconGraphic(c.iconId);
 if(c.visualType==="photo" && c.photo){const im=document.createElement("img");im.src=c.photo;im.alt="";im.className="answer-card__photo";return im;}
 if(!c.visualType && c.photo){const im=document.createElement("img");im.src=c.photo;im.alt="";im.className="answer-card__photo";return im;}
 const sp=document.createElement("span");sp.className=cls;sp.textContent=c.emoji||"💬";sp.setAttribute("aria-hidden","true");return sp;
}
