const pinConfirm=document.querySelector("#pin-confirm");
const pinConfirmLabel=document.querySelector("#pin-confirm-label");
const pinError=document.querySelector("#pin-error");
function updateMode(){
 document.body.classList.toggle("adult-mode",adultMode);
 modeButton.textContent=adultMode?"🔓 Детский режим":"🔒 Для взрослых";
 modeButton.setAttribute("aria-label",adultMode?"Вернуться в детский режим":"Открыть настройки взрослого");
 render();
}
function pinSignature(pin){
 // This local PIN is a child-safety convenience lock, not cryptographic authentication.
 let hash=2166136261;
 const value="moi-slova-pin-2026:"+pin;
 for(let i=0;i<value.length;i++){hash^=value.charCodeAt(i);hash=Math.imul(hash,16777619);}
 return (hash>>>0).toString(16);
}
function openPinDialog(){
 const setup=!localStorage.getItem(ACCESS_KEY);
 document.querySelector("#pin-title").textContent=setup?"Создать PIN взрослого":"Введите PIN взрослого";
 document.querySelector("#pin-help").textContent=setup?"Придумайте 4–8 цифр. Они понадобятся для изменения карточек. Запомните PIN: восстановление без сброса данных не предусмотрено.":"Введите PIN, чтобы добавлять, редактировать и закреплять карточки.";
 pinConfirmLabel.hidden=!setup;pinConfirm.required=setup;
 pinInput.value="";pinConfirm.value="";pinError.textContent="";
 document.querySelector("#pin-submit").textContent=setup?"Создать PIN":"Открыть настройки";
 pinDialog.showModal();pinInput.focus();
}
modeButton.addEventListener("click",()=>{if(adultMode){adultMode=false;if(dialog.open)dialog.close();updateMode();}else openPinDialog();});
document.querySelector("#pin-cancel").addEventListener("click",()=>pinDialog.close());
pinForm.addEventListener("submit",e=>{
 e.preventDefault();
 const pin=pinInput.value,setup=!localStorage.getItem(ACCESS_KEY);
 if(!/^[0-9]{4,8}$/.test(pin)){pinError.textContent="Введите от 4 до 8 цифр.";return;}
 if(setup){
  if(pin!==pinConfirm.value){pinError.textContent="PIN-коды не совпадают.";return;}
  try{localStorage.setItem(ACCESS_KEY,pinSignature(pin));}catch(e){pinError.textContent="Не удалось сохранить PIN.";return;}
 }else if(pinSignature(pin)!==localStorage.getItem(ACCESS_KEY)){pinError.textContent="Неверный PIN-код.";pinInput.select();return;}
 pinDialog.close();adultMode=true;updateMode();
});

const CATEGORY_KEY="my-words-category-v1";
const CUSTOM_CATS_KEY="moi-slova-custom-categories-v1";
const builtinCategories=[["home","🏠 Главная"],["all","Все"],["food","🍽️ Еда"],["actions","🚶 Действия"],["feelings","💛 Чувства"],["games","🧸 Игры"],["places","📍 Места"],["sequence","⏳ Время и порядок"]];
let customCategories=[];
try{
 const saved=JSON.parse(localStorage.getItem(CUSTOM_CATS_KEY)||"[]");
 if(Array.isArray(saved))customCategories=saved.filter(c=>c&&/^custom-[a-z0-9-]{3,60}$/.test(c.id)&&typeof c.name==="string"&&c.name.trim()&&typeof c.emoji==="string").slice(0,60).map(c=>({id:c.id,name:c.name.slice(0,35),emoji:c.emoji.slice(0,12)}));
}catch(e){}
const categories=[...builtinCategories,...customCategories.map(c=>[c.id,c.emoji+" "+c.name])];
function validCardCategory(id){return categories.some(([key])=>key===id&&key!=="all"&&key!=="home");}
function syncCategoryPicker(){
 const select=document.querySelector("#category");const previous=select.value;
 select.replaceChildren();
 for(const [id,label] of categories.filter(([id])=>validCardCategory(id))){
  const option=document.createElement("option");option.value=id;option.textContent=label;select.append(option);
 }
 if(validCardCategory(previous))select.value=previous;
}
function saveCustomCategories(){localStorage.setItem(CUSTOM_CATS_KEY,JSON.stringify(customCategories));}
function renderCustomCategoryManager(){
 const list=document.querySelector("#custom-category-list");if(!list)return;list.replaceChildren();
 for(const c of customCategories){
  const row=document.createElement("div");row.className="custom-category-row";
  const label=document.createElement("span");label.textContent=c.emoji+" "+c.name;
  const edit=document.createElement("button");edit.type="button";edit.textContent="✎";
  edit.setAttribute("aria-label","Изменить "+c.name);
  edit.onclick=()=>{if(!adultMode)return;const name=prompt("Название категории",c.name);if(name===null)return;
   const clean=name.trim();if(!clean||clean.length>35){alert("Введите название до 35 символов.");return;}
   const icon=prompt("Эмодзи категории",c.emoji);if(icon===null)return;
   c.name=clean;c.emoji=icon.trim().slice(0,12)||"📁";try{saveCustomCategories();}catch(e){alert("Ошибка сохранения.");return;}
   const i=categories.findIndex(([id])=>id===c.id);if(i>=0)categories[i]=[c.id,c.emoji+" "+c.name];render();syncCategoryPicker();};
  const remove=document.createElement("button");remove.type="button";remove.textContent="Удалить";
  remove.onclick=()=>{if(!adultMode)return;if(!confirm("Удалить категорию «"+c.name+"»? Её карточки переместятся в «Действия», но не удалятся."))return;
    const before=cards.map(x=>({...x}));const prior=customCategories.slice();
    cards.forEach(card=>{if(card.category===c.id)card.category="actions";});
    customCategories=customCategories.filter(x=>x.id!==c.id);
    const idx=categories.findIndex(([id])=>id===c.id);if(idx>=0)categories.splice(idx,1);
    hiddenCategories=hiddenCategories.filter(id=>id!==c.id);
    if(activeCategory===c.id)activeCategory="home";
    try{saveCustomCategories();localStorage.setItem(HIDDEN_CATEGORIES_KEY,JSON.stringify(hiddenCategories));if(!save())throw Error("save");}
    catch(e){alert("Не удалось сохранить изменения. Обновите страницу.");location.reload();return;}
    syncCategoryPicker();render();};
  row.append(label,edit,remove);list.append(row);
 }
}

const HIDDEN_CATEGORIES_KEY="moi-slova-hidden-categories-v1";
const TOGGLEABLE_CATEGORIES=categories.filter(([id])=>id!=="home").map(([id])=>id);
let hiddenCategories;
try{
 const saved=JSON.parse(localStorage.getItem(HIDDEN_CATEGORIES_KEY)||"[]");
 hiddenCategories=Array.isArray(saved)?[...new Set(saved.filter(id=>TOGGLEABLE_CATEGORIES.includes(id)))]:[];
}catch(e){hiddenCategories=[];}
function categoryVisible(id){return id==="home"||adultMode||!hiddenCategories.includes(id);}
function renderCategoryVisibility(){
 const target=document.querySelector("#category-visibility-list");if(!target)return;
 target.replaceChildren();
 for(const [id,name] of categories.filter(([id])=>TOGGLEABLE_CATEGORIES.includes(id))){
  const label=document.createElement("label");label.className="home-card-option";
  const input=document.createElement("input");input.type="checkbox";input.checked=!hiddenCategories.includes(id);
  input.addEventListener("change",()=>{
   if(!adultMode)return;
   const before=hiddenCategories.slice();
   hiddenCategories=input.checked?hiddenCategories.filter(x=>x!==id):[...hiddenCategories,id];
   try{localStorage.setItem(HIDDEN_CATEGORIES_KEY,JSON.stringify(hiddenCategories));}
   catch(e){hiddenCategories=before;input.checked=!input.checked;alert("Не удалось сохранить настройку.");return;}
   if(!categoryVisible(activeCategory))activeCategory="home";
   render();
  });
  const span=document.createElement("span");span.textContent=name;
  label.append(input,span);target.append(label);
 }
}
