function renderHomePicker(){
 const target=document.querySelector("#home-card-list");
 if(!target)return;
 target.replaceChildren();
 const counter=document.querySelector("#home-count");
 counter.textContent=`Выбрано: ${homeIds.filter(id=>cards.some(c=>c.id===id)).length}. Рекомендуется 4–6, но можно выбрать больше.`;
 for(const c of cards){
  const label=document.createElement("label");label.className="home-card-option";
  const cb=document.createElement("input");cb.type="checkbox";cb.checked=homeIds.includes(c.id);
  const txt=document.createElement("span");txt.textContent=(c.emoji||"💬")+" "+c.word;
  cb.addEventListener("change",()=>{
   const before=homeIds.slice();
   homeIds=homeIds.filter(id=>id!==c.id);
   if(cb.checked)homeIds.push(c.id);
   if(!saveHome()){homeIds=before;cb.checked=!cb.checked;return;}
   renderHomePicker();render();
  });
  label.append(cb,txt);target.append(label);
 }
}
