const word=document.querySelector("#word"),emoji=document.querySelector("#emoji"),color=document.querySelector("#color"),del=document.querySelector("#delete"),status=document.querySelector("#status"),photoInput=document.querySelector("#photo"),preview=document.querySelector("#photo-preview"),removePhoto=document.querySelector("#remove-photo");
function save(){try{localStorage.setItem(KEY,JSON.stringify(cards));return true;}catch(e){status.textContent="Не удалось сохранить. Проверьте настройки браузера.";alert("Не удалось сохранить карточки на этом устройстве.");return false;}}
// Audio recordings are stored as Blobs in IndexedDB, not in localStorage.
const DB_NAME="my-words-voice-v1",STORE="voices";
function voiceDB(){return new Promise((resolve,reject)=>{if(!("indexedDB" in window))return reject(Error("Хранилище записей недоступно"));const req=indexedDB.open(DB_NAME,1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains(STORE))req.result.createObjectStore(STORE)};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function getVoice(id){const db=await voiceDB();return new Promise((resolve,reject)=>{const tx=db.transaction(STORE,"readonly"),req=tx.objectStore(STORE).get(id);req.onsuccess=()=>resolve(req.result||null);req.onerror=()=>reject(req.error);tx.oncomplete=()=>db.close();});}
async function putVoice(id,blob){const db=await voiceDB();return new Promise((resolve,reject)=>{const tx=db.transaction(STORE,"readwrite");tx.objectStore(STORE).put(blob,id);tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>reject(tx.error);});}
async function deleteVoice(id){const db=await voiceDB();return new Promise((resolve,reject)=>{const tx=db.transaction(STORE,"readwrite");tx.objectStore(STORE).delete(id);tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>reject(tx.error);});}
function stopPlaying(){if(activeAudio){activeAudio.pause();activeAudio.src="";activeAudio=null;}if("speechSynthesis" in window)speechSynthesis.cancel();}
function playBlob(blob){stopPlaying();const url=URL.createObjectURL(blob),audio=new Audio(url);activeAudio=audio;const cleanup=()=>{URL.revokeObjectURL(url);if(activeAudio===audio)activeAudio=null;};audio.addEventListener("ended",cleanup,{once:true});audio.addEventListener("error",cleanup,{once:true});audio.play().catch(()=>{cleanup();status.textContent="Не удалось воспроизвести запись.";});}
