// Adult-only manual ordering: exchange positions inside the visible pinned or unpinned group.
// The source array order is persisted and also included in JSON backups.
function moveCardInVisibleGroup(id, direction){
 if(!adultMode)return;
 if(activeCategory==="home"){
  const index=homeIds.indexOf(id), next=index+direction;
  if(index<0||next<0||next>=homeIds.length)return;
  [homeIds[index],homeIds[next]]=[homeIds[next],homeIds[index]];
  if(!saveHome()){[homeIds[index],homeIds[next]]=[homeIds[next],homeIds[index]];return;}
  render();return;
 }
 const visible=cards.filter(c=>
  (activeCategory==="all"||isPinned(c.id)||c.category===activeCategory||
   (!c.category&&(baseCategories[c.id]||"actions")===activeCategory)) &&
  isPinned(c.id)===isPinned(id));
 const idx=visible.findIndex(c=>c.id===id), other=visible[idx+direction];
 if(idx<0||!other)return;
 const i=cards.findIndex(c=>c.id===id),j=cards.findIndex(c=>c.id===other.id);
 if(i<0||j<0)return;
 [cards[i],cards[j]]=[cards[j],cards[i]];
 if(!save()){[cards[i],cards[j]]=[cards[j],cards[i]];return;}
 // Manual positions remain stable and are not replaced by popularity reordering.
 if(sortMode!=="original"){
  sortMode="original";
  try{localStorage.setItem(SORT_KEY,"original");}catch(e){}
  document.querySelector("#sort-mode").value="original";
 }
 render();
}
function render(){
 if(scheduleOpen){renderSchedule();renderDay();}
 if(!categoryVisible(activeCategory))activeCategory="home";
 renderCategories();board.replaceChildren();if(adultMode){renderHomePicker();renderCategoryVisibility();renderCustomCategoryManager();}
 const ordered=cards.map((c,i)=>({c,i})).filter(({c})=>(activeCategory==="home"?homeIds.includes(c.id):isPinned(c.id)||activeCategory==="all"||c.category===activeCategory)||(!c.category&&(baseCategories[c.id]||"actions")===activeCategory));
 ordered.sort((a,b)=>{
   const pinA=isPinned(a.c.id),pinB=isPinned(b.c.id);
   if(activeCategory==="home")return homeIds.indexOf(a.c.id)-homeIds.indexOf(b.c.id);
   if(pinA!==pinB)return pinA?-1:1;
   if(sortMode==="popular")return (b.c.uses||0)-(a.c.uses||0)||a.i-b.i;
   return a.i-b.i;
 });
 ordered.forEach(({c})=>{
  const tile=document.createElement("div");tile.className="tile";
  if(isPinned(c.id))tile.classList.add("pinned");
  const b=document.createElement("button");b.type="button";b.className="answer-card";b.style.backgroundColor=displayColor(c);b.setAttribute("aria-label","Произнести "+c.word);
  const em=cardVisual(c);
  const label=document.createElement("span");label.className="answer-card__text";label.textContent=c.word;
  b.append(em,label);
  b.addEventListener("click",()=>{c.uses=(c.uses||0)+1;save();if(phraseModeInput.checked){if(phraseIds.length<12){phraseIds.push(c.id);renderPhrase();}}else{speakCard(c);}if(sortMode==="popular"){clearTimeout(reorderTimer);reorderTimer=setTimeout(()=>{if(!dialog.open)render();},2500);}});
  const edit=document.createElement("button");edit.hidden=!adultMode;edit.type="button";edit.className="edit";edit.textContent="✎";edit.setAttribute("aria-label","Изменить карточку "+c.word);edit.addEventListener("click",()=>openEditor(c.id));
  const pin=document.createElement("button");pin.hidden=!adultMode;pin.type="button";pin.className="pin-toggle";pin.textContent=isPinned(c.id)?"📌":"♧";
  pin.setAttribute("aria-label",(isPinned(c.id)?"Открепить ":"Закрепить ")+c.word);pin.setAttribute("aria-pressed",String(isPinned(c.id)));
  pin.title=isPinned(c.id)?"Открепить":"Закрепить наверху";pin.addEventListener("click",()=>setPinned(c.id,!isPinned(c.id)));
  const moves=document.createElement("div");moves.className="move-controls";moves.hidden=!adultMode;
  for(const [direction,arrow,label] of [[-1,"↑","Поднять"],[1,"↓","Опустить"]]){
   const control=document.createElement("button");control.type="button";
   control.className="move-card";control.textContent=arrow;
   control.setAttribute("aria-label",label+" карточку "+c.word);
   control.title=label+" карточку";
   const neighbors=activeCategory==="home"?ordered:ordered.filter(({c:x})=>isPinned(x.id)===isPinned(c.id));
   const place=neighbors.findIndex(({c:x})=>x.id===c.id);
   control.disabled=place+direction<0||place+direction>=neighbors.length;
   control.addEventListener("click",()=>moveCardInVisibleGroup(c.id,direction));
   moves.append(control);
  }
  tile.append(b,edit,pin,moves);board.append(tile);
 });
}
