// Portable, offline JSON backups (images are already embedded in cards; voice Blobs are encoded).
const backupExport=document.querySelector("#backup-export");
const backupImport=document.querySelector("#backup-import");
const backupFile=document.querySelector("#backup-file");
const backupStatus=document.querySelector("#backup-status");
function blobToDataURL(blob){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(blob);});}
function dataURLToBlob(data){
 const match=/^data:(audio\/[a-z0-9.+-]+|application\/octet-stream);base64,([A-Za-z0-9+/=]+)$/i.exec(data);
 if(!match)throw Error("Недопустимый формат голосовой записи");
 const bytes=atob(match[2]);const arr=new Uint8Array(bytes.length);
 for(let i=0;i<bytes.length;i++)arr[i]=bytes.charCodeAt(i);
 return new Blob([arr],{type:match[1]});
}
async function readAllVoices(){
 const db=await voiceDB();
 return new Promise((resolve,reject)=>{
  const tx=db.transaction(STORE,"readonly"),store=tx.objectStore(STORE);
  const result={};const request=store.openCursor();
  request.onsuccess=()=>{const cursor=request.result;if(cursor){if(typeof cursor.key==="string" && cursor.value instanceof Blob)result[cursor.key]=cursor.value;cursor.continue();}};
  request.onerror=()=>reject(request.error);
  tx.oncomplete=()=>{db.close();resolve(result)};
  tx.onerror=()=>{db.close();reject(tx.error)};
 });
}
async function replaceAllVoices(voices){
 const db=await voiceDB();
 return new Promise((resolve,reject)=>{
  const tx=db.transaction(STORE,"readwrite"),store=tx.objectStore(STORE);
  store.clear();
  Object.entries(voices).forEach(([id,blob])=>store.put(blob,id));
  tx.oncomplete=()=>{db.close();resolve()};
  tx.onerror=()=>{db.close();reject(tx.error)};
 });
}

// Visual first-then schedule. Existing cards are referenced by ID; photos and personal voices are reused.
const SCHEDULE_KEY="moi-slova-first-then-v1";
function defaultSchedule(){
 const first=cards.find(c=>c.word.toUpperCase()==="УЧИТЬСЯ")?.id||cards[0]?.id||"";
 const next=cards.find(c=>c.word.toUpperCase()==="ИГРАТЬ")?.id||cards[1]?.id||first;
 return [first,next];
}
function readSchedule(){
 try{const ids=JSON.parse(localStorage.getItem(SCHEDULE_KEY)||"null");
 if(Array.isArray(ids)&&ids.length===2&&ids.every(id=>typeof id==="string"))return ids;
 }catch(e){}
 return defaultSchedule();
}
let scheduleIds=readSchedule();
const schedulePanel=document.querySelector("#schedule-panel");
const firstSelect=document.querySelector("#schedule-first-select");
const nextSelect=document.querySelector("#schedule-next-select");
function scheduleCurrent(){
 return scheduleIds.map((id,i)=>cards.find(c=>c.id===id)||cards.find(c=>c.id===defaultSchedule()[i])||null);
}
function showSchedule(){
 document.body.classList.toggle("schedule-open",scheduleOpen);
 schedulePanel.hidden=!scheduleOpen;
 document.querySelector("#first-then-content").hidden=dayView;
 document.querySelector("#day-content").hidden=!dayView;
 document.querySelector("#schedule-open").setAttribute("aria-pressed",String(scheduleOpen));
 if(scheduleOpen){renderSchedule();renderDay();}
}
function renderSchedule(){
 const current=scheduleCurrent();
 for(const [i,select,target] of [[0,firstSelect,document.querySelector("#schedule-first")],[1,nextSelect,document.querySelector("#schedule-next")]]){
  select.replaceChildren();
  for(const c of cards){
   const option=document.createElement("option");option.value=c.id;option.textContent=(c.emoji||"💬")+" "+c.word;select.append(option);
  }
  select.value=current[i]?.id||"";
  target.replaceChildren();
  const c=current[i];
  if(!c){target.textContent="Выберите карточку";target.style.background="#f1f1f1";continue;}
  target.style.background=displayColor(c);
  target.append(cardVisual(c,"schedule-emoji"));
  const name=document.createElement("span");name.textContent=c.word;target.append(name);
 }
}
function changeSchedule(i,value){
 scheduleIds[i]=value;
 try{localStorage.setItem(SCHEDULE_KEY,JSON.stringify(scheduleIds));}catch(e){alert("Не удалось сохранить расписание.");}
 renderSchedule();
}
