let scheduleSpeaking=false;
document.querySelector("#schedule-say").addEventListener("click",async()=>{
 if(scheduleSpeaking||phrasePlaying)return;
 scheduleSpeaking=true;
 const button=document.querySelector("#schedule-say");button.disabled=true;
 stopPlaying();
 try{
  const current=scheduleCurrent();
  for(let i=0;i<2;i++){
   const intro=i===0?"Сначала":"Потом";
   if("speechSynthesis" in window)await new Promise(resolve=>{
    const utterance=configureUtterance(new SpeechSynthesisUtterance(intro));
    utterance.onend=resolve;utterance.onerror=resolve;
    speechSynthesis.speak(utterance);
   });
   if(current[i])await playPhraseWord(current[i]);
  }
 }finally{scheduleSpeaking=false;button.disabled=false;}
});


// Daily visual schedule: stable card references, child-facing progress and adult editing.
const DAY_KEY="moi-slova-day-schedule-v1";
function defaultDay(){
 const words=["ЕСТЬ","УЧИТЬСЯ","ГУЛЯТЬ","ОТДЫХАТЬ","СПАТЬ"];
 return words.map(w=>cards.find(c=>c.word.toUpperCase()===w)?.id).filter(Boolean).map(id=>({id,done:false}));
}
function validatedDay(value){
 if(!Array.isArray(value))return null;
 return value.slice(0,30).filter(s=>s&&typeof s.id==="string"&&cards.some(c=>c.id===s.id))
 .map(s=>({id:s.id,done:s.done===true}));
}
function readDay(){
 try{const v=validatedDay(JSON.parse(localStorage.getItem(DAY_KEY)||"null"));if(v)return v;}catch(e){}
 return defaultDay();
}
let daySteps=readDay();
function saveDay(){
 try{localStorage.setItem(DAY_KEY,JSON.stringify(daySteps));}
 catch(e){alert("Недостаточно памяти для сохранения расписания.");}
 renderDay();
}
const dayList=document.querySelector("#day-steps");
function renderDay(){
 if(!dayList)return;
 const selector=document.querySelector("#day-add-card");
 const existing=selector.value;
 selector.replaceChildren();
 cards.forEach(c=>{const o=document.createElement("option");o.value=c.id;o.textContent=(c.emoji||"💬")+" "+c.word;selector.append(o);});
 if(cards.some(c=>c.id===existing))selector.value=existing;
 dayList.replaceChildren();
 const complete=daySteps.filter(s=>s.done).length;
 document.querySelector("#day-progress").textContent=daySteps.length?`Выполнено ${complete} из ${daySteps.length}`:"Пока нет действий. Взрослый может добавить карточки.";
 daySteps.forEach((step,i)=>{
  const c=cards.find(c=>c.id===step.id);if(!c)return;
  const wrap=document.createElement("div");wrap.className="day-step"+(step.done?" is-done":"");
  const tick=document.createElement("button");tick.type="button";tick.className="day-check";tick.textContent=step.done?"✓":"○";tick.setAttribute("aria-label",(step.done?"Отметить невыполненным: ":"Выполнено: ")+c.word);
  tick.addEventListener("click",()=>{daySteps[i].done=!daySteps[i].done;saveDay();});
  const card=document.createElement("button");card.type="button";card.className="day-card";card.style.background=displayColor(c);
  const image=cardVisual(c,"day-emoji");
  const word=document.createElement("strong");word.textContent=c.word;
  card.append(image,word);card.addEventListener("click",()=>{stopPlaying();playPhraseWord(c);});
  const number=document.createElement("span");number.className="day-number";number.textContent=String(i+1);
  wrap.append(number,tick,card);
  if(adultMode){
   const controls=document.createElement("div");controls.className="day-controls";
   for(const [label,delta] of [["↑",-1],["↓",1]]){
    const btn=document.createElement("button");btn.type="button";btn.textContent=label;btn.disabled=i+delta<0||i+delta>=daySteps.length;
    btn.addEventListener("click",()=>{const other=i+delta;[daySteps[i],daySteps[other]]=[daySteps[other],daySteps[i]];saveDay();});controls.append(btn);
   }
   const remove=document.createElement("button");remove.type="button";remove.textContent="✕";remove.setAttribute("aria-label","Удалить шаг "+c.word);
   remove.addEventListener("click",()=>{daySteps.splice(i,1);saveDay();});controls.append(remove);wrap.append(controls);
  }
  dayList.append(wrap);
 });
}
document.querySelector("#view-first").addEventListener("click",()=>{dayView=false;showSchedule();});
document.querySelector("#view-day").addEventListener("click",()=>{dayView=true;showSchedule();});
document.querySelector("#day-back").addEventListener("click",()=>{scheduleOpen=false;showSchedule();});
document.querySelector("#day-add-button").addEventListener("click",()=>{
 if(!adultMode||daySteps.length>=30)return;
 const id=document.querySelector("#day-add-card").value;if(!cards.some(c=>c.id===id))return;
 daySteps.push({id,done:false});saveDay();
});
document.querySelector("#day-reset-progress").addEventListener("click",()=>{
 if(!adultMode)return;daySteps.forEach(s=>s.done=false);saveDay();
});
document.querySelector("#day-reset-example").addEventListener("click",()=>{
 if(!adultMode||!confirm("Заменить расписание примером?"))return;daySteps=defaultDay();saveDay();
});
let daySpeaking=false;
document.querySelector("#day-say").addEventListener("click",async()=>{
 if(daySpeaking||phrasePlaying||scheduleSpeaking)return;
 daySpeaking=true;const btn=document.querySelector("#day-say");btn.disabled=true;
 stopPlaying();
 try{
  for(const item of [...daySteps]){
   const c=cards.find(c=>c.id===item.id);if(c)await playPhraseWord(c);
  }
 }finally{daySpeaking=false;btn.disabled=false;}
});

function localSettings(){
 return {[HOME_KEY]:localStorage.getItem(HOME_KEY),[HOME_MIGRATION_KEY]:localStorage.getItem(HOME_MIGRATION_KEY),[KEY]:localStorage.getItem(KEY),
 [PIN_KEY]:localStorage.getItem(PIN_KEY),
 [SORT_KEY]:localStorage.getItem(SORT_KEY),
 [CATEGORY_KEY]:localStorage.getItem(CATEGORY_KEY),
 [EXPANSION_KEY]:localStorage.getItem(EXPANSION_KEY),
 [ACCESS_KEY]:localStorage.getItem(ACCESS_KEY),
 [COLOR_MODE_KEY]:localStorage.getItem(COLOR_MODE_KEY),
 [TTS_VOICE_KEY]:localStorage.getItem(TTS_VOICE_KEY),
 [TTS_RATE_KEY]:localStorage.getItem(TTS_RATE_KEY),
 [SIZE_KEY]:localStorage.getItem(SIZE_KEY),
 [STABLE_MIGRATION_KEY]:localStorage.getItem(STABLE_MIGRATION_KEY),
 [IMPORTANT_EXPANSION_KEY]:localStorage.getItem(IMPORTANT_EXPANSION_KEY),
 [HIDDEN_CATEGORIES_KEY]:localStorage.getItem(HIDDEN_CATEGORIES_KEY),[CUSTOM_CATS_KEY]:localStorage.getItem(CUSTOM_CATS_KEY),[SCHEDULE_KEY]:localStorage.getItem(SCHEDULE_KEY),[DAY_KEY]:localStorage.getItem(DAY_KEY),[PLACES_MIGRATION_KEY]:localStorage.getItem(PLACES_MIGRATION_KEY)};
}
function restoreSettings(settings){
 for(const key of Object.keys(localSettings())){
  if(settings[key]===null||settings[key]===undefined)localStorage.removeItem(key);
  else localStorage.setItem(key,settings[key]);
 }
}
backupExport.addEventListener("click",async()=>{
 if(!adultMode)return;
 backupExport.disabled=true;backupStatus.textContent="Готовим резервную копию…";
 try{
  // Read the latest saved cards, including photo data and usage counters.
  const audio=await readAllVoices();
  const voices={};
  for(const [id,blob] of Object.entries(audio))voices[id]=await blobToDataURL(blob);
  const payload={format:"moi-slova-backup",version:1,createdAt:new Date().toISOString(),
   cards:JSON.parse(localStorage.getItem(KEY)||JSON.stringify(cards)),
   settings:{homeIds:homeIds, pins:pinnedIds,sort:sortMode,category:activeCategory,pinSignature:localStorage.getItem(ACCESS_KEY),colorMode,ttsVoice:chosenVoice,ttsRate,cardSize,hiddenCategories,customCategories,scheduleIds,daySteps},
   voices};
  const blob=new Blob([JSON.stringify(payload)],{type:"application/json"});
  const url=URL.createObjectURL(blob);
  const a=document.createElement("a");
  a.href=url;a.download="moi-slova-backup-"+new Date().toISOString().slice(0,10)+".json";
  document.body.append(a);a.click();a.remove();
  setTimeout(()=>URL.revokeObjectURL(url),30000);
  backupStatus.textContent="Файл создан. Убедитесь, что он сохранён в файлах устройства.";
 }catch(e){backupStatus.textContent="Не удалось создать копию: "+e.message;}
 finally{backupExport.disabled=false;}
});
backupImport.addEventListener("click",()=>{if(adultMode)backupFile.click();});
backupFile.addEventListener("change",async()=>{
 if(!adultMode)return;
 const file=backupFile.files?.[0];backupFile.value="";
 if(!file)return;
 if(file.size>150*1024*1024){backupStatus.textContent="Файл больше 150 МБ. Восстановление отменено.";return;}
 backupImport.disabled=true;backupStatus.textContent="Проверяем резервную копию…";
 try{
  const obj=JSON.parse(await file.text());
  if(obj?.format!=="moi-slova-backup"||obj.version!==1||!Array.isArray(obj.cards)||typeof obj.voices!=="object"||obj.voices===null||Array.isArray(obj.voices)||typeof obj.settings!=="object"||obj.settings===null)throw Error("Этот файл не является совместимой резервной копией.");
  if(obj.cards.length>3000)throw Error("Слишком много карточек.");
  const restoredCustom=Array.isArray(obj.settings.customCategories)?obj.settings.customCategories.filter(c=>c&&/^custom-[a-z0-9-]{3,60}$/.test(c.id)&&typeof c.name==="string"&&c.name.trim()&&c.name.length<=35&&typeof c.emoji==="string").slice(0,60):[];
  const backupCategories=new Set([...categories.map(c=>c[0]),...restoredCustom.map(c=>c.id)]);
  const ids=new Set(),safeCards=[];
  for(const c of obj.cards){
   if(!c||typeof c.id!=="string"||c.id.length>150||typeof c.word!=="string"||!c.word.trim()||c.word.length>45||ids.has(c.id))throw Error("Некорректные или повторяющиеся карточки.");
   ids.add(c.id);
   if(c.photo!==null&&c.photo!==undefined&&(typeof c.photo!=="string"||!/^data:image\/(jpeg|png|webp);base64,/i.test(c.photo)))throw Error("Недопустимое фото.");
   safeCards.push({id:c.id,word:c.word,emoji:String(c.emoji||"💬").slice(0,12),color:colors.has(c.color)?c.color:"#c9d9ff",
    category:backupCategories.has(c.category)&&!["home","all"].includes(c.category)?c.category:"actions",
    photo:c.photo||null,visualType:["emoji","photo","icon"].includes(c.visualType)?c.visualType:(c.photo?"photo":"emoji"),iconId:BUILTIN_ICON_PATHS[c.iconId]?c.iconId:"home",uses:Number.isSafeInteger(c.uses)&&c.uses>=0?c.uses:0});
  }
  const voices={};
  for(const [id,data] of Object.entries(obj.voices)){
   if(!ids.has(id)||typeof data!=="string")throw Error("Некорректная голосовая запись.");
   voices[id]=dataURLToBlob(data);
  }
  const settings=obj.settings;
  const restoredHome=Array.isArray(settings.homeIds)?[...new Set(settings.homeIds.filter(id=>typeof id==="string"&&ids.has(id)))]:HOME_DEFAULT.filter(id=>ids.has(id));
  const restoredPins=Array.isArray(settings.pins)?settings.pins.filter(id=>typeof id==="string"&&ids.has(id)):[];
  const restoredHidden=Array.isArray(settings.hiddenCategories)?[...new Set(settings.hiddenCategories.filter(id=>backupCategories.has(id)&&id!=="home"))]:[];
  const restoredSort=settings.sort==="popular"?"popular":"original";
  const restoredColorMode=["semantic","neutral","custom"].includes(settings.colorMode)?settings.colorMode:"semantic";
  const restoredVoice=typeof settings.ttsVoice==="string"?settings.ttsVoice:"";
  const restoredRate=[0.75,0.85,0.95,1,1.1].includes(Number(settings.ttsRate))?Number(settings.ttsRate):0.85;
  const restoredCategory=categories.some(([id])=>id===settings.category)?settings.category:"all";
  const restoredPin=typeof settings.pinSignature==="string"&&/^[0-9a-f]{1,8}$/i.test(settings.pinSignature)?settings.pinSignature:null;
  if(!confirm("Восстановление ЗАМЕНИТ все текущие карточки, фотографии, записи голоса, статистику и PIN. Перед продолжением сохраните копию текущих данных. Продолжить?")){backupStatus.textContent="Восстановление отменено.";return;}
  const previousSettings=localSettings(),previousVoices=await readAllVoices();
  try{
   await replaceAllVoices(voices);
   localStorage.setItem(KEY,JSON.stringify(safeCards));
   localStorage.setItem(PIN_KEY,JSON.stringify(restoredPins));
   localStorage.setItem(HOME_KEY,JSON.stringify(restoredHome));
   localStorage.setItem(HOME_MIGRATION_KEY,"done");
   localStorage.setItem(SORT_KEY,restoredSort);
   localStorage.setItem(COLOR_MODE_KEY,restoredColorMode);
   localStorage.setItem(HIDDEN_CATEGORIES_KEY,JSON.stringify(restoredHidden));
   localStorage.setItem(CUSTOM_CATS_KEY,JSON.stringify(restoredCustom));
   const restoredSchedule=Array.isArray(settings.scheduleIds)&&settings.scheduleIds.length===2?settings.scheduleIds.map(x=>typeof x==="string"&&ids.has(x)?x:""):[];
   if(restoredSchedule.length===2)localStorage.setItem(SCHEDULE_KEY,JSON.stringify(restoredSchedule));else localStorage.removeItem(SCHEDULE_KEY);
   localStorage.setItem(PLACES_MIGRATION_KEY,"done");
   localStorage.setItem(TTS_VOICE_KEY,restoredVoice);
   localStorage.setItem(TTS_RATE_KEY,String(restoredRate));
   localStorage.setItem(CATEGORY_KEY,restoredCategory);
   localStorage.setItem(EXPANSION_KEY,"done");
   if(restoredPin)localStorage.setItem(ACCESS_KEY,restoredPin);else localStorage.removeItem(ACCESS_KEY);
  }catch(e){
   try{restoreSettings(previousSettings);await replaceAllVoices(previousVoices);}catch(rollbackError){console.error("Ошибка отката",rollbackError);}
   throw e;
  }
  // Reset adult mode and reload to prevent stale references to restored cards.
  backupStatus.textContent="Данные восстановлены. Перезапускаем приложение…";
  location.reload();
 }catch(e){backupStatus.textContent="Не удалось восстановить: "+e.message;}
 finally{backupImport.disabled=false;}
});
